##
# Logging Settings
##

access_log /var/log/nginx/access.log;

log_format benchmark '$time_local $request_method $status "$http_user_agent"';
limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

##
# Logging Settings
##

access_log /var/log/nginx/access.log;

log_format benchmark '$time_local $request_method $status "$http_user_agent"';
limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

arguments.command:
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name localhost;
    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    location / {
        limit_req zone=benchmark_limit burst=10 nodelay;
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF

# insert log_format and limit_req_zone into http block if not present
grep -q 'log_format benchmark' /etc/nginx/nginx.conf || \
sed -i 's|\taccess_log /var/log/nginx/access.log;|\taccess_log /var/log/nginx/access.log;\n\n\tlog_format benchmark '"'"'$time_local $request_method $status "$http_user_agent"'"'"';\n\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;|' /etc/nginx/nginx.conf

mkdir -p /var/www/html
echo "Welcome to the benchmark webserver" > /var/www/html/index.html
echo "Page not found - Please check your URL" > /var/www/html/404.html
rm -f /etc/nginx/sites-enabled/default

grep -n 'log_format benchmark\|limit_req_zone' /etc/nginx/nginx.conf
nginx -t 2>&1

